/**
 * Golden parity: lib/costing/engine.ts against the real Python engine. ONE set of 60 cases (tests/fixtures/costing-golden.json, generated by
 * running services/costing-engine/app/services/quoting_enhanced.py calc_detailed_quote + to_dict; ChatGPT's and Claude's copies of the fixture
 * are byte-identical). Every case must equal the Python dict exactly, and pyRound must give CPython's round() for the 100+ recorded tie cases.
 *
 * The engine has NO built-in rates, but the Python engine does (margin 15%, programming 75/hr, overhead x1.5) and some of the 60 cases leave
 * those out. PYTHON_FALLBACKS below lives ONLY in this test: it fills the three keys a case omits with the values Python used when the fixture
 * was generated, so the expected output (c.dict) is unchanged. It proves the arithmetic; it is not a company rate and the app never uses it.
 */
import { readFileSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

import { calcDetailedQuote, pyRound, type DetailedInputs } from "../../lib/costing/engine";

type Op = Record<string, number | string | undefined> & { name: string; sequence: number };
type Input = { quantity: number; scrap_factor: number; ops: Op[]; programming_time_hr?: number; programming_rate_per_hr?: number;
  first_article_inspection_hr?: number; margin_pct?: number; overhead_rate_pct?: number } & Record<string, unknown>;
type GoldenCase = { name: string; input: Input; raw: unknown; dict: unknown };
type Golden = { source: { file: string; commit: string; sha256: string }; cases: GoldenCase[]; py_round: { x: number; n: number; out: number }[] };

const GOLDEN = JSON.parse(readFileSync(path.resolve(__dirname, "../fixtures/costing-golden.json"), "utf8")) as Golden;
const PYTHON_FALLBACKS = { margin_pct: 0.15, programming_rate_per_hr: 75, overhead_rate_pct: 1.5 };
const withPythonFallbacks = (input: Input) => ({ ...PYTHON_FALLBACKS, ...structuredClone(input) }) as unknown as DetailedInputs;

describe("costing golden fixtures", () => {
  it("ship all 60 frozen Python cases from the real engine file", () => {
    expect(GOLDEN.source.file).toBe("services/costing-engine/app/services/quoting_enhanced.py");
    expect(GOLDEN.source.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(GOLDEN.cases).toHaveLength(60);
    const quantities = GOLDEN.cases.map((c) => c.input.quantity);
    expect(Math.min(...quantities)).toBe(1);
    expect(Math.max(...quantities)).toBe(1000);
    const some = (f: (c: GoldenCase) => boolean) => GOLDEN.cases.some(f);
    const anyOp = (key: string) => some((c) => c.input.ops.some((o) => Number(o[key] ?? 0) > 0));
    expect(some((c) => c.input.ops.length === 0)).toBe(true);
    expect(some((c) => c.input.ops.length >= 4)).toBe(true);
    expect(some((c) => (c.input.programming_time_hr ?? 0) > 0)).toBe(true);
    expect(some((c) => (c.input.first_article_inspection_hr ?? 0) > 0)).toBe(true);
    expect(some((c) => c.input.programming_rate_per_hr === undefined)).toBe(true);
    expect(some((c) => c.input.margin_pct === undefined)).toBe(true);
    expect(some((c) => c.input.margin_pct === 0)).toBe(true);
    expect(some((c) => c.input.scrap_factor === 0) && some((c) => c.input.scrap_factor >= 0.3)).toBe(true);
    for (const key of ["tool_cost_per_part", "tool_change_time_min", "inspection_time_min", "consumables_cost_per_part"]) expect(anyOp(key)).toBe(true);
    expect(GOLDEN.py_round.length).toBeGreaterThan(100);
  });
});

describe("lib/costing/engine.ts matches the Python engine (60 cases)", () => {
  it.each(GOLDEN.cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    expect(calcDetailedQuote(withPythonFallbacks(c.input))).toEqual(c.dict);
  });

  it.each(GOLDEN.py_round.map((r, i) => [i, r] as const))("pyRound case %i", (_i, r) => {
    expect(Object.is(pyRound(r.x, r.n), r.out)).toBe(true);
  });

  it("rounds 21.125 down to 21.12 at an exact pence tie", () => {
    const result = calcDetailedQuote({
      quantity: 10, stock_weight_lb: 0, cost_per_lb: 0, scrap_factor: 0,
      ops: [{ name: "Mill", sequence: 1, setup_time_hr: 0, cycle_time_hr: 0.325, allowance_pct: 0, machine_rate_per_hr: 65, labor_rate_per_hr: 0 }],
      programming_rate_per_hr: 0, overhead_rate_pct: 1, margin_pct: 0,
    });
    expect(result.cost_breakdown.machine_cost).toBe(21.12);
  });
});
